"""OpenAPI document of the server (SPECIFICATION §7), generated by FastAPI and completed here:

- ``Problem`` / ``FieldError`` (RFC 9457 errors) are added as components;
- ``FormatOptions`` = ``oneOf`` the option models of every registered format (each format's ``config_schema``),
  and every ``format_options`` property points at it, so the document describes each format's options.
"""

from __future__ import annotations

from typing import Any

from fastapi import FastAPI
from fastapi.openapi.utils import get_openapi

from waystation_server.formats.registry import FormatRegistry
from waystation_server.problems import Problem

REF = '#/components/schemas/{model}'


def _add_model(schemas: dict[str, Any], schema: dict[str, Any]) -> None:
    for name, sub in schema.pop('$defs', {}).items():
        schemas.setdefault(name, sub)


def build(app: FastAPI, registry: FormatRegistry) -> dict[str, Any]:
    doc = get_openapi(title=app.title, version=app.version, routes=app.routes, description=app.description)
    schemas: dict[str, Any] = doc.setdefault('components', {}).setdefault('schemas', {})
    problem = Problem.model_json_schema(ref_template=REF)
    _add_model(schemas, problem)
    schemas['Problem'] = problem
    refs = []
    for descriptor in registry.descriptors():
        model = descriptor.options_model
        schema = model.model_json_schema(ref_template=REF)
        _add_model(schemas, schema)
        name = str(schema.get('title') or model.__name__)
        schemas[name] = schema
        refs.append({'$ref': REF.format(model=name)})
    schemas['FormatOptions'] = {
        'description': "Format-specific options; the shape follows the repository's `format`",
        'oneOf': refs,
    }
    for name, schema in schemas.items():
        if name == 'FormatOptions':
            continue
        props = schema.get('properties', {})
        if 'format_options' in props:
            props['format_options'] = {'$ref': REF.format(model='FormatOptions')}
    return doc


def install(app: FastAPI, registry: FormatRegistry) -> None:
    def openapi() -> dict[str, Any]:
        if app.openapi_schema is None:
            app.openapi_schema = build(app, registry)
        return app.openapi_schema

    app.openapi = openapi  # type: ignore[method-assign]
